package com.mediconnect.controller;
import com.mediconnect.dto.ApiDtos;import com.mediconnect.entity.*;import com.mediconnect.repository.*;import org.springframework.http.*;import org.springframework.security.core.annotation.AuthenticationPrincipal;import org.springframework.web.bind.annotation.*;import org.springframework.web.server.ResponseStatusException;import java.util.*;
@RestController @RequestMapping("/api/reviews")
public class ReviewController{
 private final ReviewRepository repo;private final AppointmentRepository appointments;
 public ReviewController(ReviewRepository r,AppointmentRepository a){repo=r;appointments=a;}
 @GetMapping("/doctor/{id}") public List<ApiDtos.ReviewView> doctor(@AuthenticationPrincipal User viewer,@PathVariable Long id){if(viewer.getHospital()==null)throw forbidden("Hospital membership required");return repo.findByDoctorIdOrderByCreatedAtDesc(id).stream().filter(r->r.getHospital()!=null&&r.getHospital().getId().equals(viewer.getHospital().getId())).map(ApiDtos.ReviewView::of).toList();}
 @GetMapping public List<ApiDtos.ReviewView> mine(@AuthenticationPrincipal User u){
  if(u.getRole()==Role.PLATFORM_SUPER_ADMIN)throw new org.springframework.web.server.ResponseStatusException(org.springframework.http.HttpStatus.FORBIDDEN,"Platform administrators do not have clinical record access");if(u.getRole()==Role.ADMIN)return repo.findByHospitalIdOrderByCreatedAtDesc(u.getHospital().getId()).stream().map(ApiDtos.ReviewView::of).toList();
  if(u.getRole()==Role.DOCTOR)return repo.findByDoctorIdOrderByCreatedAtDesc(u.getId()).stream().map(ApiDtos.ReviewView::of).toList();
  return repo.findByPatientIdOrderByCreatedAtDesc(u.getId()).stream().map(ApiDtos.ReviewView::of).toList();
}
 @PostMapping public ApiDtos.ReviewView create(@AuthenticationPrincipal User patient,@RequestBody Map<String,Object>b){Long aid=id(b.get("appointmentId"));Appointment a=appointments.findById(aid==null?-1:aid).orElseThrow(()->bad("Appointment not found"));if(patient.getRole()!=Role.PATIENT||!a.getPatient().getId().equals(patient.getId())||patient.getHospital()==null||a.getHospital()==null||!patient.getHospital().getId().equals(a.getHospital().getId()))throw forbidden("Only the patient can review this appointment");if(a.getStatus()!=AppointmentStatus.COMPLETED)throw bad("Only completed appointments can be reviewed");if(repo.findByAppointmentId(a.getId()).isPresent())throw new ResponseStatusException(HttpStatus.CONFLICT,"Appointment already reviewed");int rating;try{rating=Integer.parseInt(String.valueOf(b.get("rating")));}catch(Exception e){rating=0;}if(rating<1||rating>5)throw bad("Rating must be between 1 and 5");Review r=new Review();r.setHospital(patient.getHospital());r.setPatient(patient);r.setDoctor(a.getDoctor());r.setAppointment(a);r.setRating(rating);r.setComment(b.get("comment")==null?"":String.valueOf(b.get("comment")));return ApiDtos.ReviewView.of(repo.save(r));}
 private static Long id(Object o){try{return Long.valueOf(String.valueOf(o));}catch(Exception e){return null;}}private static ResponseStatusException bad(String m){return new ResponseStatusException(HttpStatus.BAD_REQUEST,m);}private static ResponseStatusException forbidden(String m){return new ResponseStatusException(HttpStatus.FORBIDDEN,m);}
}
